def gen(rng):
    alpha = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,!?-_'
    def word(maxlen):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(1, maxlen)))
    def sentence(nw, maxlen):
        return ' '.join(word(maxlen) for _ in range(nw))
    def fmt(ls):
        return str(len(ls)) + '\n' + '\n'.join(ls)
    tests = [fmt(['hello']), fmt(['a b']), fmt(['one two three four five']), fmt(['x', 'y z', 'p q r'])]
    for _ in range(40):
        n = rng.randint(1, 4)
        tests.append(fmt([sentence(rng.randint(1, 5), 6) for _ in range(n)]))
    # large: 1000 lines, 100 chars each
    tests.append(fmt([sentence(rng.randint(10, 20), 8) for _ in range(1000)]))
    # one long line of single-char words
    tests.append(fmt([' '.join(rng.choice(alpha) for _ in range(1000))]))
    tests.append(fmt([sentence(60, 30) for _ in range(50)]))
    tests.append(fmt([word(1999)] + [sentence(300, 5) for _ in range(40)]))
    return tests
